"use strict";

var crypto = require("crypto");

// Guessing the password: after LIMIT different wrong passwords from one
// client within WINDOW, that client gets 429 for BLOCK, without its
// credentials being checked. The same wrong password sent again (a tab
// that still has an old one) counts once. Wrong passwords, blocks and the
// first login from an address each day are logged (journalctl -u cloud9).
var LIMIT = 10;
var WINDOW = 15 * 60 * 1000;
var BLOCK = 15 * 60 * 1000;
var LOGIN_LOG_EVERY = 24 * 60 * 60 * 1000;
var MAX_TRACKED = 10000;            // addresses remembered at most (the oldest go first)
var REALM = "Authorization Required";

module.exports = function(options, imports, register) {
    if (!options.username || !options.password)
        return register();

    // compare digests so the check takes the same time for every guess
    function digest(user, pass) {
        return crypto.createHash("sha256").update(user + ":" + pass).digest();
    }
    var expected = digest(options.username, options.password);

    var failures = new Map();       // address -> { since, wrong: Set of digests, blockedUntil, refused }
    var logins = new Map();         // address -> when its login was last logged

    var connect = imports.connect;
    connect.useSetup(function(req, res, next) {
        if (req.user) return next();

        var client = clientAddress(req);
        var now = Date.now();
        var record = failures.get(client);
        if (record && record.blockedUntil) {
            if (now < record.blockedUntil) {
                record.refused++;
                return tooManyAttempts(res, record.blockedUntil - now);
            }
            console.warn("Login: " + client + " may try again (" + record.refused
                + " requests were refused while it was blocked)");
            failures.delete(client);
            record = null;
        }
        else if (record && now - record.since > WINDOW) {
            failures.delete(client);
            record = null;
        }

        var authorization = req.headers.authorization;
        if (!authorization) return unauthorized(res);

        var parts = authorization.split(" ");
        var credentials = parts.length == 2 && parts[0] == "Basic"
            ? Buffer.from(parts[1], "base64").toString() : "";
        var index = credentials.indexOf(":");
        if (index < 0) return next(badRequest());

        var user = credentials.slice(0, index);
        var given = digest(user, credentials.slice(index + 1));
        if (crypto.timingSafeEqual(given, expected)) {
            logLogin(client, user, now);
            req.user = req.remoteUser = user;
            return next();
        }

        if (!record) {
            record = { since: now, wrong: new Set(), blockedUntil: 0, refused: 0 };
            remember(failures, client, record);
        }
        var key = given.toString("hex");
        if (!record.wrong.has(key)) {
            record.wrong.add(key);
            console.warn("Login: wrong username or password for " + JSON.stringify(user.slice(0, 64))
                + " from " + client + " (" + record.wrong.size + " of " + LIMIT + ")");
            if (record.wrong.size >= LIMIT) {
                record.blockedUntil = now + BLOCK;
                console.warn("Login: blocking " + client + " for " + BLOCK / 60000
                    + " minutes after " + LIMIT + " wrong passwords");
                return tooManyAttempts(res, BLOCK);
            }
        }
        unauthorized(res);
    });

    // the first login from an address each day, so the log shows who got
    // in from where
    function logLogin(client, user, now) {
        var last = logins.get(client);
        if (last && now - last < LOGIN_LOG_EVERY) return;
        remember(logins, client, now);
        console.log("Login: " + JSON.stringify(user.slice(0, 64)) + " from " + client);
    }

    console.log("Using basic authentication (at most " + LIMIT + " wrong passwords per address in "
        + WINDOW / 60000 + " minutes)");

    register();
};

// The client's address. Behind a reverse proxy on this machine (Apache,
// nginx) every request comes from loopback, and the client is the last
// address the proxy added to X-Forwarded-For (one the client sent itself
// comes before it).
function clientAddress(req) {
    var socket = req.socket || req.connection || {};
    var peer = String(socket.remoteAddress || "").replace(/^::ffff:/, "");
    var forwarded = req.headers["x-forwarded-for"];
    if (forwarded && /^(127\.|::1$)/.test(peer)) {
        var last = String(forwarded).split(",").pop().trim();
        if (last) return last.slice(0, 64);
    }
    return peer || "unknown";
}

// a bounded map: the oldest entries go first
function remember(map, key, value) {
    map.delete(key);
    map.set(key, value);
    if (map.size > MAX_TRACKED)
        map.delete(map.keys().next().value);
}

function unauthorized(res) {
    res.statusCode = 401;
    res.setHeader("WWW-Authenticate", 'Basic realm="' + REALM + '"');
    res.end("Unauthorized");
}

function tooManyAttempts(res, ms) {
    var minutes = Math.ceil(ms / 60000);
    res.statusCode = 429;
    res.setHeader("Retry-After", String(Math.ceil(ms / 1000)));
    res.setHeader("Content-Type", "text/plain");
    res.end("Too many failed logins from your address. Try again in " + minutes
        + (minutes == 1 ? " minute." : " minutes."));
}

function badRequest() {
    var err = new Error("Bad Request");
    err.status = 400;
    return err;
}
